func fitJSONItems(items []json.RawMessage, build func([]json.RawMessage) any) []byte {
	limit := len(items)
	if limit > MaxItems {
		limit = MaxItems
	}
	for n := limit; n > 0; n-- {
		out, err := json.Marshal(build(items[:n]))
		if err != nil {
			continue
		}
		if len(out) <= MaxBytes {
			return out
		}
	}
	out, _ := json.Marshal(build(items[:0]))
	return out
}

func fitJSONPageItems(items []json.RawMessage, start int, currentUpstream, nextUpstream string, build func([]json.RawMessage, string, string) any) []byte {
	remaining := len(items) - start
	if remaining < 0 {
		remaining = 0
	}
	limit := remaining
	if limit > MaxItems {
		limit = MaxItems
	}
	for n := limit; n > 0; n-- {
		next := nextPageCursor(start+n, len(items), currentUpstream, nextUpstream)
		out, err := json.Marshal(build(items[start:start+n], "", next))
		if err != nil {
			continue
		}
		if len(out) <= MaxBytes {
			return out
		}
	}
	if start < len(items) {
		next := nextPageCursor(start+1, len(items), currentUpstream, nextUpstream)
		previewLimit := maxPreviewBytes
		for previewLimit >= 0 {
			out, err := json.Marshal(build(nil, previewString(items[start], previewLimit), next))
			if err == nil && len(out) <= MaxBytes {
				return out
			}
			if previewLimit == 0 {
				break
			}
			if previewLimit < 512 {
				previewLimit = 0
			} else {
				previewLimit -= 512
			}
		}
	}
	next := nextPageCursor(len(items), len(items), currentUpstream, nextUpstream)
	out, _ := json.Marshal(build(nil, "", next))
	return out
}

func nextPageCursor(nextOffset, itemCount int, currentUpstream, nextUpstream string) string {
	state := endpointCursor{Version: 1}
	switch {
	case nextOffset < itemCount:
		state.Offset = nextOffset
		state.UpstreamCursor = currentUpstream
	case nextUpstream != "":
		state.UpstreamCursor = nextUpstream
	default:
		return ""
	}
	return encodeEndpointCursor(state)
}

func encodeEndpointCursor(state endpointCursor) string {
	if state.Version == 0 {
		state.Version = 1
	}
	data, err := json.Marshal(state)
	if err != nil {
		return ""
	}
	return base64.RawURLEncoding.EncodeToString(data)
}

func decodeEndpointCursor(cursor string) (endpointCursor, error) {
	if cursor == "" {
		return endpointCursor{Version: 1}, nil
	}
	data, err := base64.RawURLEncoding.DecodeString(cursor)
	if err != nil {
		return endpointCursor{}, fmt.Errorf("invalid MCP cursor")
	}
	var state endpointCursor
	if err := json.Unmarshal(data, &state); err != nil {
		return endpointCursor{}, fmt.Errorf("invalid MCP cursor")
	}
	if state.Version != 1 {
		return endpointCursor{}, fmt.Errorf("unsupported MCP cursor version")
	}
	if state.Offset < 0 {
		return endpointCursor{}, fmt.Errorf("invalid MCP cursor offset")
	}
	return state, nil
}

func extractStringPath(data json.RawMessage, path string) string {
	v, ok := extractPath(data, path)
	if !ok {
		return ""
	}
	s, _ := v.(string)
	return s
}

// extractPath traverses a dotted response path (object keys only, no array
// indexing) and returns the raw decoded value at that path. json.Unmarshal
// decodes JSON numbers as float64 and JSON booleans as bool, so callers
// type-assert the concrete shape they expect.
func extractPath(data json.RawMessage, path string) (any, bool) {
	path = strings.TrimSpace(path)
	if path == "" {
		return nil, false
	}
	var v any
	if json.Unmarshal(data, &v) != nil {
		return nil, false
	}
	for _, part := range strings.Split(path, ".") {
		obj, ok := v.(map[string]any)
		if !ok {
			return nil, false
		}
		v, ok = obj[part]
		if !ok {
			return nil, false
		}
	}
	return v, true
}

// extractNextIntegerPage implements PageOptions' integer-page-number
// pagination fallback: when the response reports a boolean "more pages
// exist" flag at indicatorPath and the current page number at numberPath,
// it returns the next page number as a string (suitable as an outgoing
// UpstreamCursor / CursorParam value). Returns "" if either path is unset,
// missing, or not the expected type -- callers already treat "" as "no
// more pages" via nextPageCursor's default case, so this degrades safely.
func extractNextIntegerPage(data json.RawMessage, indicatorPath, numberPath string) string {
	if indicatorPath == "" || numberPath == "" {
		return ""
	}
	hasNext, ok := extractPath(data, indicatorPath)
	if !ok {
		return ""
	}
	if b, ok := hasNext.(bool); !ok || !b {
		return ""
	}
	current, ok := extractPath(data, numberPath)
	if !ok {
		return ""
	}
	n, ok := current.(float64)
	if !ok {
		return ""
	}
	return strconv.Itoa(int(n) + 1)
}

func previewEnvelope(data []byte, note string) string {
	limit := len(data)
	if limit > maxPreviewBytes {
		limit = maxPreviewBytes
	}
	for limit >= 0 {
		out, err := json.Marshal(map[string]any{
			"truncated":      true,
			"resumable":      false,
			"original_bytes": len(data),
			"max_bytes":      MaxBytes,
			"preview":        previewString(data, limit),
			"note":           note,
		})
		if err == nil && len(out) <= MaxBytes {
			return string(out)
		}
		if limit == 0 {
			break
		}
		if limit < 512 {
			limit = 0
		} else {
			limit -= 512
		}
	}
	out, _ := json.Marshal(map[string]any{
		"truncated":      true,
		"resumable":      false,
		"original_bytes": len(data),
		"max_bytes":      MaxBytes,
		"note":           note,
	})
	return string(out)
}

func previewString(data []byte, limit int) string {
	if limit > len(data) {
		limit = len(data)
	}
	for limit > 0 {
		r, size := utf8.DecodeLastRune(data[:limit])
		if r != utf8.RuneError || size != 1 {
			break
		}
		limit--
	}
	return string(data[:limit])
}
